function validate([root1, root2]) {
  // Walk a level-order array the way it is read: every node takes the next two slots as its children.
  const count = (values, name) => {
    if (!Array.isArray(values) || values.length === 0 || values[0] === null) return `${name} needs at least one node.`;
    const queue = [0];
    let next = 1;
    for (let head = 0; head < queue.length; head++) {
      const value = values[queue[head]];
      if (value !== '+' && !(typeof value === 'string' && /^[a-z]$/.test(value))) return `Every node of ${name} is "+" or one lowercase letter.`;
      let children = 0;
      for (let side = 0; side < 2; side++) {
        if (next < values.length && values[next] !== null) {
          queue.push(next);
          children++;
        }
        next++;
      }
      if (value === '+' && children !== 2) return `Every "+" in ${name} needs two children.`;
      if (value !== '+' && children !== 0) return `Letters in ${name} must be leaves.`;
    }
    if (values.slice(next).some(value => value !== null)) return `${name} has values that are not attached to the tree.`;
    if (queue.length > 4999) return `${name} has at most 4999 nodes.`;
    return queue.length;
  };
  const first = count(root1, 'root1');
  if (typeof first === 'string') return first;
  const second = count(root2, 'root2');
  if (typeof second === 'string') return second;
  if (first !== second) return 'Both trees must have the same number of nodes.';
  return null;
}

