function adapt(input, solve, kit) {
  // Rebuild a tree from its level-order array: each node takes the next two entries as its children.
  const build = values => {
    const root = new kit.Node(values[0]);
    const queue = [root];
    let next = 1;
    for (let head = 0; head < queue.length && next < values.length; head++) {
      for (const side of ['left', 'right']) {
        if (next < values.length && values[next] !== null) {
          queue[head][side] = new kit.Node(values[next]);
          queue.push(queue[head][side]);
        }
        next++;
      }
    }
    return root;
  };
  const [root1, root2] = input;
  const result = solve(build(root1), build(root2));
  if (typeof result !== 'boolean') throw new Error('Return true or false.');
  return result;
}

