function checkEquivalence(root1, root2) {
  const counts = new Array(26).fill(0);
  const tally = (node, delta) => {
    if (node.val === '+') {
      tally(node.left, delta);
      tally(node.right, delta);
    } else {
      counts[node.val.charCodeAt(0) - 97] += delta;
    }
  };
  tally(root1, 1);
  tally(root2, -1);
  return counts.every(count => count === 0);
}

