function checkEquivalence(root1, root2) {
  // List each tree's leaves with an explicit stack, sort them, and compare the two lists.
  const leaves = root => {
    const found = [];
    const stack = [root];
    while (stack.length) {
      const node = stack.pop();
      if (node.left || node.right) stack.push(node.left, node.right);
      else found.push(node.val);
    }
    return found.sort().join('');
  };
  return leaves(root1) === leaves(root2);
}

