function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const leafCount = size === 'large' ? 400 + pick(100) : 1 + pick(6);
  const alphabet = size === 'large' ? 26 : 1 + pick(4);
  const letter = () => String.fromCharCode(97 + pick(alphabet));
  // Join random pairs of subtrees under '+', or grow one long chain, until a single tree is left.
  const build = letters => {
    const pool = letters.map(val => ({ val, left: null, right: null }));
    if (rand() < 0.3) {
      let tree = pool[0];
      for (let i = 1; i < pool.length; i++) tree = rand() < 0.5 ? { val: '+', left: tree, right: pool[i] } : { val: '+', left: pool[i], right: tree };
      return tree;
    }
    while (pool.length > 1) {
      const a = pool.splice(pick(pool.length), 1)[0];
      const b = pool.splice(pick(pool.length), 1)[0];
      pool.push({ val: '+', left: a, right: b });
    }
    return pool[0];
  };
  const serialize = root => {
    const out = [];
    const queue = [root];
    for (let q = 0; q < queue.length; q++) {
      const node = queue[q];
      if (node === null) { out.push(null); continue; }
      out.push(node.val);
      queue.push(node.left, node.right);
    }
    while (out[out.length - 1] === null) out.pop();
    return out;
  };
  const first = Array.from({ length: leafCount }, letter);
  let second = first.slice();
  const mode = rand();
  if (mode < 0.35) {
    // One leaf gets a different letter, so the counts no longer match.
    const i = pick(leafCount);
    second[i] = String.fromCharCode(97 + (second[i].charCodeAt(0) - 97 + 1 + pick(alphabet > 1 ? alphabet - 1 : 25)) % 26);
  } else if (mode < 0.5) {
    second = Array.from({ length: leafCount }, letter);
  }
  for (let i = second.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [second[i], second[j]] = [second[j], second[i]];
  }
  return [serialize(build(first)), serialize(build(second))];
}
